function onMessage(e) {
  const d = e.data || {};
  if (d.type === 'SKIP_WAITING') self.skipWaiting();
  else if (d.type === 'WARM') e.waitUntil(warm());
  else if (d.type === 'VERSION' && e.source) e.source.postMessage({ type: 'VERSION', version: BUILD.version });
}
